/**
 * #58: the worker runtime is generated by stringifying functions. A minifier
 * renames those functions, so a call by the original name (randomId()) dangles
 * and every sandbox Worker fails with "randomId is not defined". Bundle and
 * minify the library, then run a real sandbox from the minified output.
 */
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildSync } from 'esbuild';

const entry = fileURLToPath(new URL('../src/index.mjs', import.meta.url));
const workerSource = fileURLToPath(new URL('../src/worker-source.mjs', import.meta.url));

function minify(entryPoint, outfile) {
  buildSync({
    entryPoints: [entryPoint],
    bundle: true,
    minify: true,
    format: 'esm',
    platform: 'node',
    outfile,
    logLevel: 'silent',
  });
}

describe('minified build (#58)', () => {
  it('runs a real sandbox from a minified bundle', () => {
    const dir = mkdtempSync(join(tmpdir(), 'andbox-min-'));
    try {
      const out = join(dir, 'andbox.min.mjs');
      minify(entry, out);
      const runner = join(dir, 'run.mjs');
      writeFileSync(runner, `
import { createSandbox } from './andbox.min.mjs';
const sb = await createSandbox({ capabilities: { add: (a, b) => a + b } });
try {
  console.log(JSON.stringify(await sb.evaluate('return [1 + 2, await host.call("add", 2, 3)]')));
} finally {
  await sb.dispose();
}
`);
      const res = execFileSync(process.execPath, [runner], { encoding: 'utf8' });
      assert.equal(res.trim().split('\n').pop(), '[3,5]');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('generated runtime source defines every helper it calls, when minified', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'andbox-min-'));
    try {
      const out = join(dir, 'worker-source.min.mjs');
      minify(workerSource, out);
      const { makeRuntimeSource } = await import(out);
      const src = makeRuntimeSource({ networkFetch: true, bridges: true });
      assert.match(src, /\bconst randomId\s*=/, 'randomId is bound by name');
      assert.doesNotThrow(() => new Function(src.replace(/^\s*(import|export)\b.*$/gm, '')), 'parses');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
